const fullRender=render,fullGo=go;let interfaceMode='operations';
const symbols={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',receive:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',prepare:'<path d="m4 7 8-4 8 4v10l-8 4-8-4zM4 7l8 4 8-4M12 11v10"/>',move:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',check:'<path d="m5 12 4 4L19 6"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${symbols[name]||symbols.grid}</svg>`}
const mgmt=['Inventário','Notas fiscais','Embalagens','Cadastros','Movimentações'];
go=function(v){if(mgmt.includes(v))interfaceMode='management';if(v==='Início'||v==='Preparar'||v==='Movimentar')interfaceMode='operations';fullGo(v)};
function switchInterface(mode){interfaceMode=mode;fullGo(mode==='operations'?'Início':'Inventário')}
function operationGroup(){return view==='Recebimento'?'receive':['Conferência','Preparar','Encaixotamento','Etiquetas'].includes(view)?'prepare':['Movimentar','Transferir caixas','Separação'].includes(view)?'move':'home'}
function workQueue(){const checks=pendingItems().map(p=>({name:p.name,detail:`${p.qty} ${p.unit} · ${p.lot||'Sem lote'} · ${p.receiptId||'Exemplo'}`,status:'Conferir',icon:'check',action:`inspectItem('${p.id}','${p.kind}')`}));const pack=inspections.flatMap((r,n)=>r.scanPacking&&packingRemainder(n)>0?[{name:r.name,detail:`${packingRemainder(n)} pops · lote ${r.lot}`,status:'Encaixotar',icon:'prepare',action:`packingPage(${n})`}]:[]);return [...checks,...pack]}
function queueHTML(limit){const all=workQueue(),items=limit?all.slice(0,limit):all;return items.length?items.map(t=>`<button class="task-row" onclick="${t.action}"><span class="task-icon">${icon(t.icon)}</span><span class="task-copy"><strong>${esc(t.name)}</strong><small>${esc(t.detail)}</small></span><span class="task-status">${t.status}</span>${icon('arrow')}</button>`).join(''):'<div class="queue-empty">'+icon('check')+'<h3>Tudo em dia por aqui</h3><p>Novos recebimentos aparecerão nesta fila.</p></div>'}
function actionCard(title,desc,symbol,action,kicker){return `<button class="action-card" onclick="${action}"><span class="action-top"><span class="action-icon ${symbol}">${icon(symbol)}</span><span class="action-number">${kicker}</span></span><strong>${title}</strong><span class="action-description">${desc}</span><span class="action-footer">Abrir ${icon('arrow')}</span></button>`}
function homeHTML(){const queue=workQueue(),open=boxes.filter(b=>b.active&&b.qty>0).length;return `<div class="heading"><div><div class="eyebrow">OPERAÇÃO YOLO</div><h1>O que vamos fazer agora?</h1><p>Escolha uma ação ou continue uma tarefa abaixo.</p></div><span class="site-label">São Paulo · Estoque</span></div><div class="action-grid">${actionCard('Receber','Registrar produtos, nota fiscal e caixas de entrada.','receive','receive()','01')}${actionCard('Preparar','Conferir, classificar e encaixotar os produtos.','prepare',"go('Preparar')",'02')}${actionCard('Movimentar','Transferir caixas e separar produtos para saída.','move',"go('Movimentar')",'03')}</div><section class="work-panel"><div class="work-heading"><div><h2>Continuar de onde parou</h2><p>${queue.length?`${queue.length} tarefa${queue.length===1?'':'s'} aguardando ação`:'Nenhuma pendência operacional'}</p></div>${queue.length>4?'<button class="text-button" onclick="go(\'Preparar\')">Ver todas</button>':''}</div>${queueHTML(4)}</section><div class="quiet-summary"><span>${icon('prepare')} ${open} caixas em separação</span><span>Dados de demonstração · alterações apenas nesta sessão</span></div>`}
function prepareHTML(){return `<div class="heading"><div><div class="eyebrow">02 / PREPARAR</div><h1>Uma etapa de cada vez.</h1><p>Abra uma tarefa para conferir ou continuar o encaixotamento.</p></div></div><div class="flow-bar"><span>1. Conferir quantidades</span><span>2. Classificar</span><span>3. Vincular caixas</span><span>4. Etiquetar</span></div><section class="work-panel"><div class="work-heading"><h2>A fazer <span class="count-pill">${workQueue().length}</span></h2></div>${queueHTML()}</section>${inspections.length?`<details class="panel completed-work"><summary>Conferências anteriores (${inspections.length})</summary>${inspections.map((r,n)=>`<button class="task-row" onclick="inspectionResult(${n})"><span class="task-copy"><strong>${esc(r.name)}</strong><small>${esc(r.lot||'Sem lote')} · ${r.actual} ${esc(r.unit)} conferidos</small></span>${icon('arrow')}</button>`).join('')}</details>`:''}`}
function moveHTML(){return `<div class="heading"><div><div class="eyebrow">03 / MOVIMENTAR</div><h1>Caixas no lugar certo.</h1><p>Movimente caixas inteiras ou retire unidades de uma caixa de separação.</p></div></div><div class="action-grid two">${actionCard('Transferir caixas','Escaneie um grupo de caixas e escolha o destino.','move',"go('Transferir caixas')",'LOTE')}${actionCard('Separar produtos','Abra uma caixa, registre retiradas e acompanhe o saldo.','prepare',"go('Separação')",'UNIDADES')}</div>`}
function paintShell(){const group=operationGroup(),op=interfaceMode==='operations';document.body.dataset.interface=interfaceMode;document.querySelector('.brand').innerHTML='YOLO<span>OS <i>•</i> Operações</span>';const opNav=[['Início','home','Início'],['Receber','receive','Recebimento'],['Preparar','prepare','Preparar'],['Movimentar','move','Movimentar']];$('nav').innerHTML=op?opNav.map(([label,sym,target])=>`<button class="${group===sym?'active':''}" onclick="go('${target}')">${icon(sym)}<span>${label}</span></button>`).join(''):mgmt.map(label=>`<button class="${view===label?'active':''}" onclick="go('${label}')">${icon(label==='Movimentações'?'history':'grid')}<span>${label}</span></button>`).join('');document.querySelector('header').innerHTML=`<div class="workspace-crumb"><span class="workspace-mark">Y</span><span>YOLO OS <span class="crumb-divider">/</span> ${op?'Operação':'Gestão'}</span></div><div class="mode-switch" aria-label="Interface"><button class="${op?'selected':''}" aria-pressed="${op}" onclick="switchInterface('operations')">Operação</button><button class="${!op?'selected':''}" aria-pressed="${!op}" onclick="switchInterface('management')">Gestão</button></div><span class="avatar" title="Usuário de demonstração">OP</span>`;document.querySelector('.asidefoot').innerHTML='<span class="sidebar-caption">AMBIENTE</span><strong>YOLO · São Paulo</strong><small>Protótipo de demonstração<br>Sem login ou dados permanentes</small>';}
render=function(){fullRender();if(view==='Início')$('app').innerHTML=homeHTML();if(view==='Preparar'||view==='Conferência')$('app').innerHTML=prepareHTML();if(view==='Movimentar')$('app').innerHTML=moveHTML();const redundant=$('app').querySelector('.heading > button[onclick="receive()"]');if(redundant)redundant.remove();paintShell()};
render();
